UPDATE STUDENTS
SET NAME = #{student.name},
	LEARNING_START_DATE = #{student.learningStartDate, jdbcType=DATE},
	CURRENT_LEVEL = #{student.currentLevel, jdbcType=VARCHAR},
	INSTRUCTOR_MEMO = #{student.instructorMemo, jdbcType=VARCHAR}
WHERE ID = #{student.id}
	AND INSTRUCTOR_ID = #{instructorId}

mapper.delete:

DELETE FROM STUDENTS
WHERE ID = #{id}
	AND INSTRUCTOR_ID = #{instructorId}
